import sys
from collections import deque

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    grid = [list(row) for row in data[2:2 + n]]

    q = deque()

    # Encontra a posição inicial do 'o'
    for c in range(m):
        if grid[0][c] == 'o':
            q.append((0, c))
            break

    while q:
        r, c = q.popleft()

        # Água tenta escorrer para baixo
        if r + 1 < n:
            if grid[r + 1][c] == '.':
                grid[r + 1][c] = 'o'
                q.append((r + 1, c))
            elif grid[r + 1][c] == '#':
                # Se há uma prateleira logo abaixo, a água escorre para os lados
                if c - 1 >= 0 and grid[r][c - 1] == '.':
                    grid[r][c - 1] = 'o'
                    q.append((r, c - 1))
                if c + 1 < m and grid[r][c + 1] == '.':
                    grid[r][c + 1] = 'o'
                    q.append((r, c + 1))

    output = [''.join(row) for row in grid]
    sys.stdout.write('\n'.join(output) + '\n')

if __name__ == '__main__':
    solve()
